codeExamples.code:
-- Top of hierarchy
CREATE TABLE dim_department (
    department_key   INT          PRIMARY KEY,
    department_name  VARCHAR(60)  NOT NULL
);

-- Mid level references department
CREATE TABLE dim_category (
    category_key     INT          PRIMARY KEY,
    category_name    VARCHAR(60)  NOT NULL,
    department_key   INT          NOT NULL REFERENCES dim_department(department_key)
);

-- Leaf dimension references category (fact joins here)
CREATE TABLE dim_product (
    product_key      INT          PRIMARY KEY,
    sku              VARCHAR(20)  NOT NULL,
    product_name     VARCHAR(150),
    category_key     INT          NOT NULL REFERENCES dim_category(category_key)
);

-- Fact joins only to the leaf dimension
CREATE TABLE fact_sales (
    sales_key    BIGINT PRIMARY KEY,
    date_key     INT    NOT NULL,
    product_key  INT    NOT NULL REFERENCES dim_product(product_key),
    quantity     INT    NOT NULL,
    sale_amount  DECIMAL(12,2) NOT NULL
);
